/**
 * Return the previous/next element of a list.
 *
 * @param {array} list    The list of elements
 * @param activeElement   The active element
 * @param shouldGetNext   Choose to get next or previous element
 * @param isCycleAllowed
 * @return {Element|elem} The proper element
 */
const getNextActiveElement = (list, activeElement, shouldGetNext, isCycleAllowed) => {
  if (list.length === 0) {
    return null;
  }

  let index = list.indexOf(activeElement);

  // If activeElement not found, start from the beginning if moving forward,
  // or from the end if moving backward.
  if (index === -1) {
    index = shouldGetNext ? 0 : list.length - 1;
  }

  const startIndex = index;
  let found = false;
  do {
    index += shouldGetNext ? 1 : -1;

    if (isCycleAllowed) {
      if (index >= list.length) {
        index = 0;
      } else if (index < 0) {
        index = list.length - 1;
      }
    } else {
      // If we reach the end of the list without cycling, return the activeElement
      if (index >= list.length || index < 0) {
        return activeElement;
      }
    }

    if (!isDisabled(list[index])) {
      return list[index];
    }
  } while (index !== startIndex);

  // All elements are disabled; return the original activeElement
  return activeElement;
}
